import{_ as r,C as i,o as t,c as n,a2 as a,b as c,w as o,a as s,E as l,a3 as h}from"./chunks/framework.DZUUNQ77.js";const f=JSON.parse('{"title":"BinderInvocationStub · 假 IBinder","description":"","frontmatter":{},"headers":[],"relativePath":"reference/client/binder-invocation-stub.md","filePath":"reference/client/binder-invocation-stub.md","lastUpdated":1784063681000}'),b={name:"reference/client/binder-invocation-stub.md"};function u(p,e,v,S,B,I){const d=i("Mermaid");return t(),n("div",null,[e[1]||(e[1]=a('<h1 id="binderinvocationstub-·-假-ibinder" tabindex="-1">BinderInvocationStub · 假 IBinder <a class="header-anchor" href="#binderinvocationstub-·-假-ibinder" aria-label="Permalink to &quot;BinderInvocationStub · 假 IBinder&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">源码路径</p><p><a href="https://github.com/android-security-engineer/VirtualXposed-skills/blob/vxp/VirtualApp/lib/src/main/java/com/lody/virtual/client/hook/base/BinderInvocationStub.java" target="_blank" rel="noreferrer"><code>src/main/java/com/lody/virtual/client/hook/base/BinderInvocationStub.java</code></a></p></div><p><code>BinderInvocationStub</code> 继承 <a href="./method-invocation-stub"><code>MethodInvocationStub&lt;IInterface&gt;</code></a> 并实现 <code>IBinder</code>。它是一个<strong>假的 IBinder</strong>——<code>queryLocalInterface</code> 返回带满 <code>MethodProxy</code> 的动态代理，从而让 <code>ServiceManager.getService(name)</code> 拿到的就是这个假 binder。48 个服务代理替换 <code>ServiceManager.sCache</code> 的物理基础就是它。</p><h2 id="与父类的区别" tabindex="-1">与父类的区别 <a class="header-anchor" href="#与父类的区别" aria-label="Permalink to &quot;与父类的区别&quot;">​</a></h2><p><code>MethodInvocationStub</code> 包的是「接口调用」；<code>BinderInvocationStub</code> 多包了一层「binder 句柄」：</p><table tabindex="0"><thead><tr><th>层</th><th>谁负责</th><th>干什么</th></tr></thead><tbody><tr><td>IBinder</td><td><code>BinderInvocationStub</code></td><td>实现 <code>transact</code>/<code>queryLocalInterface</code>，伪装成真 binder</td></tr><tr><td>IInterface</td><td>父类 <code>MethodInvocationStub</code></td><td>动态代理按方法名分发到 <code>MethodProxy</code></td></tr></tbody></table><h2 id="构造方式" tabindex="-1">构造方式 <a class="header-anchor" href="#构造方式" aria-label="Permalink to &quot;构造方式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>构造</th><th>用途</th></tr></thead><tbody><tr><td><code>BinderInvocationStub(RefStaticMethod asInterfaceMethod, IBinder binder)</code></td><td>用 mirror 反射的 <code>asInterface</code> 把原 binder 转接口</td></tr><tr><td><code>BinderInvocationStub(Class&lt;?&gt; stubClass, IBinder binder)</code></td><td>用 <code>StubClass.asInterface</code> 反射转换</td></tr><tr><td><code>BinderInvocationStub(IInterface mBaseInterface)</code></td><td>已有接口直接包</td></tr></tbody></table><h2 id="replaceservice" tabindex="-1">replaceService <a class="header-anchor" href="#replaceservice" aria-label="Permalink to &quot;replaceService&quot;">​</a></h2><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> void</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> replaceService</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(String name)</span></span></code></pre></div><p>把自己写进 <code>ServiceManager.sCache[name]</code>（或对应版本的缓存字段），此后所有 <code>Context.getSystemService</code> / <code>ServiceManager.getService</code> 拿到的都是这个假 binder。这是整个 hook 注入的「临门一脚」。</p><h2 id="内嵌-asbinder" tabindex="-1">内嵌 AsBinder <a class="header-anchor" href="#内嵌-asbinder" aria-label="Permalink to &quot;内嵌 AsBinder&quot;">​</a></h2><p><code>AsBinder</code> 是内部 <code>MethodProxy</code>，hook 的是 <code>asBinder()</code> 方法——当 App 通过接口取底层 binder 时，返回 <code>BinderInvocationStub</code> 自己，保持闭环。</p><h2 id="binder-替换闭环" tabindex="-1">binder 替换闭环 <a class="header-anchor" href="#binder-替换闭环" aria-label="Permalink to &quot;binder 替换闭环&quot;">​</a></h2>',14)),(t(),c(h,null,{default:o(()=>[l(d,{id:"mermaid-113",class:"mermaid",graph:"flowchart%20LR%0A%20%20APP%5B%22App%20getSystemService%22%5D%20--%3E%20SM%5B%22ServiceManager.getService%22%5D%0A%20%20SM%20--%3E%20CACHE%5B%22sCache%5Bname%5D%22%5D%0A%20%20CACHE%20--%3E%20BS%5B%22BinderInvocationStub%3Cbr%2F%3E(%E5%81%87%20IBinder)%22%5D%0A%20%20BS%20--%3E%7C%22queryLocalInterface%22%7C%20PROXY%5B%22%E5%8A%A8%E6%80%81%E4%BB%A3%E7%90%86%3Cbr%2F%3E(%E6%8C%82%E6%BB%A1%20MethodProxy)%22%5D%0A%20%20PROXY%20--%3E%7C%22%E6%8C%89%E6%96%B9%E6%B3%95%E5%90%8D%E5%88%86%E5%8F%91%22%7C%20MP%5B%22%E5%90%84%20MethodProxy%22%5D%0A%20%20PROXY%20-.-%3E%7C%22asBinder()%22%7C%20BS%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="./method-invocation-proxy"><code>BinderInvocationProxy</code></a>：持有它并触发 <code>replaceService</code>。</li><li><a href="./method-invocation-stub"><code>MethodInvocationStub</code></a>：父类，提供分发能力。</li><li><a href="./../../features/service-hook">系统服务 Hook</a>：整体机制。</li><li><a href="./../../features/ipc-bridge">IPC 桥</a>：binder 替换的背景。</li></ul>',2))])}const k=r(b,[["render",u]]);export{f as __pageData,k as default};
